-- Generado con npm run supabase:sql. Solo esquema, reglas y catálogo oficial.
-- No contiene cuentas, contraseñas, fotos ni sesiones. Ejecutar en SQL Editor como postgres.
-- Si gymbro ya existe, aborta sin borrar ni sobrescribir nada.
BEGIN;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='gymbro')
THEN RAISE EXCEPTION 'El esquema gymbro ya existe: no se modifica. Usar migraciones para actualizarlo.'; END IF; END $$;
CREATE SCHEMA gymbro;
SET LOCAL search_path TO gymbro, public;

CREATE TABLE IF NOT EXISTS "gymbro"."users" ("id" UUID , "email" VARCHAR(255) NOT NULL UNIQUE, "password_hash" VARCHAR(255) NOT NULL, "ai_week_start" TIMESTAMP WITH TIME ZONE, "ai_weekly_used" INTEGER NOT NULL DEFAULT 0, "password_changed_at" TIMESTAMP WITH TIME ZONE, "name" VARCHAR(255) NOT NULL, "goal" VARCHAR(255), "height_cm" INTEGER, "gym_name" VARCHAR(255), "discipline" VARCHAR(255), "photo_url" TEXT, "leaderboard_opt_in" BOOLEAN NOT NULL DEFAULT false, "created_at" TIMESTAMP WITH TIME ZONE NOT NULL, "updated_at" TIMESTAMP WITH TIME ZONE NOT NULL, "deleted_at" TIMESTAMP WITH TIME ZONE, PRIMARY KEY ("id"));

CREATE TABLE IF NOT EXISTS "gymbro"."user_rest_days" ("id" UUID , "weekday" INTEGER NOT NULL, "user_id" UUID NOT NULL REFERENCES "gymbro"."users" ("id") ON DELETE CASCADE ON UPDATE CASCADE, PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "user_rest_days_user_id_weekday" ON "gymbro"."user_rest_days" ("user_id", "weekday");

CREATE TABLE IF NOT EXISTS "gymbro"."routines" ("id" UUID , "name" VARCHAR(255) NOT NULL, "goal" VARCHAR(255) NOT NULL, "active" BOOLEAN DEFAULT true, "created_at" TIMESTAMP WITH TIME ZONE NOT NULL, "deleted_at" TIMESTAMP WITH TIME ZONE, "user_id" UUID NOT NULL REFERENCES "gymbro"."users" ("id") ON DELETE CASCADE ON UPDATE CASCADE, PRIMARY KEY ("id"));

CREATE TABLE IF NOT EXISTS "gymbro"."welcome_plans" ("id" UUID , "preferences" JSONB NOT NULL, "proposal" JSONB NOT NULL, "source" VARCHAR(16) NOT NULL, "accepted_at" TIMESTAMP WITH TIME ZONE, "skipped_at" TIMESTAMP WITH TIME ZONE, "created_at" TIMESTAMP WITH TIME ZONE NOT NULL, "updated_at" TIMESTAMP WITH TIME ZONE NOT NULL, "user_id" UUID NOT NULL REFERENCES "gymbro"."users" ("id") ON DELETE CASCADE ON UPDATE CASCADE, "routine_id" UUID REFERENCES "gymbro"."routines" ("id") ON DELETE SET NULL ON UPDATE CASCADE, PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "welcome_plans_user_id" ON "gymbro"."welcome_plans" ("user_id");

CREATE TABLE IF NOT EXISTS "gymbro"."exercises" ("id" UUID , "name" VARCHAR(255) NOT NULL, "normalized_name" VARCHAR(255) NOT NULL, "muscle_group" VARCHAR(255) NOT NULL, "equipment" VARCHAR(255) NOT NULL, "movement_pattern" VARCHAR(255), "description" TEXT, "video_url" TEXT, "training_type" VARCHAR(255) NOT NULL DEFAULT 'POWER', "deleted_at" TIMESTAMP WITH TIME ZONE, "created_by_user_id" UUID REFERENCES "gymbro"."users" ("id") ON DELETE RESTRICT ON UPDATE CASCADE, PRIMARY KEY ("id"));

CREATE TABLE IF NOT EXISTS "gymbro"."routine_days" ("favorite" BOOLEAN NOT NULL DEFAULT false, "id" UUID , "name" VARCHAR(255) NOT NULL, "day_number" INTEGER NOT NULL, "deleted_at" TIMESTAMP WITH TIME ZONE, "routine_id" UUID NOT NULL REFERENCES "gymbro"."routines" ("id") ON DELETE CASCADE ON UPDATE CASCADE, PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "routine_days_routine_id_day_number" ON "gymbro"."routine_days" ("routine_id", "day_number");

CREATE TABLE IF NOT EXISTS "gymbro"."routine_exercises" ("id" UUID , "order" INTEGER NOT NULL, "target_sets" INTEGER NOT NULL, "min_reps" INTEGER NOT NULL, "max_reps" INTEGER NOT NULL, "rest_seconds" INTEGER DEFAULT 90, "target_duration_minutes" INTEGER, "target_distance_km" DECIMAL(7,2), "intensity" VARCHAR(255), "deleted_at" TIMESTAMP WITH TIME ZONE, "routine_day_id" UUID NOT NULL REFERENCES "gymbro"."routine_days" ("id") ON DELETE CASCADE ON UPDATE CASCADE, "exercise_id" UUID NOT NULL REFERENCES "gymbro"."exercises" ("id") ON DELETE CASCADE ON UPDATE CASCADE, PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "routine_exercises_routine_day_id_order" ON "gymbro"."routine_exercises" ("routine_day_id", "order");

CREATE TABLE IF NOT EXISTS "gymbro"."routine_schedules" ("id" UUID , "weekday" INTEGER NOT NULL, "start_time" TIME NOT NULL, "end_time" TIME NOT NULL, "created_at" TIMESTAMP WITH TIME ZONE NOT NULL, "updated_at" TIMESTAMP WITH TIME ZONE NOT NULL, "routine_day_id" UUID NOT NULL REFERENCES "gymbro"."routine_days" ("id") ON DELETE CASCADE ON UPDATE CASCADE, PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "routine_schedules_routine_day_id_weekday_start_time_end_time" ON "gymbro"."routine_schedules" ("routine_day_id", "weekday", "start_time", "end_time");

DO 'BEGIN CREATE TYPE "gymbro"."enum_training_sessions_status" AS ENUM(''ACTIVE'', ''PAUSED'', ''COMPLETED'', ''CANCELLED''); EXCEPTION WHEN duplicate_object THEN null; END';

CREATE TABLE IF NOT EXISTS "gymbro"."training_sessions" ("id" UUID , "started_at" TIMESTAMP WITH TIME ZONE, "finished_at" TIMESTAMP WITH TIME ZONE, "duration_seconds" INTEGER, "status" "gymbro"."enum_training_sessions_status" DEFAULT 'ACTIVE', "calories" DECIMAL(7,2), "total_volume_kg" DECIMAL(12,2), "deleted_at" TIMESTAMP WITH TIME ZONE, "user_id" UUID NOT NULL REFERENCES "gymbro"."users" ("id") ON DELETE CASCADE ON UPDATE CASCADE, "routine_day_id" UUID REFERENCES "gymbro"."routine_days" ("id") ON DELETE SET NULL ON UPDATE CASCADE, PRIMARY KEY ("id"));

CREATE INDEX "training_sessions_user_id_started_at" ON "gymbro"."training_sessions" ("user_id", "started_at");

CREATE TABLE IF NOT EXISTS "gymbro"."performed_exercises" ("id" UUID , "order" INTEGER NOT NULL, "deleted_at" TIMESTAMP WITH TIME ZONE, "session_id" UUID NOT NULL REFERENCES "gymbro"."training_sessions" ("id") ON DELETE CASCADE ON UPDATE CASCADE, "exercise_id" UUID NOT NULL REFERENCES "gymbro"."exercises" ("id") ON DELETE CASCADE ON UPDATE CASCADE, PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "performed_exercises_session_id_order" ON "gymbro"."performed_exercises" ("session_id", "order");

CREATE TABLE IF NOT EXISTS "gymbro"."performed_sets" ("id" UUID , "set_number" INTEGER NOT NULL, "weight_kg" DECIMAL(7,2) NOT NULL, "repetitions" INTEGER NOT NULL, "duration_seconds" INTEGER, "actual_rest_seconds" INTEGER, "completed_at" TIMESTAMP WITH TIME ZONE, "deleted_at" TIMESTAMP WITH TIME ZONE, "performed_exercise_id" UUID NOT NULL REFERENCES "gymbro"."performed_exercises" ("id") ON DELETE CASCADE ON UPDATE CASCADE, PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "performed_sets_performed_exercise_id_set_number" ON "gymbro"."performed_sets" ("performed_exercise_id", "set_number");

CREATE TABLE IF NOT EXISTS "gymbro"."body_weight_histories" ("id" UUID , "weight_kg" DECIMAL(5,2) NOT NULL, "recorded_at" TIMESTAMP WITH TIME ZONE, "deleted_at" TIMESTAMP WITH TIME ZONE, "user_id" UUID NOT NULL REFERENCES "gymbro"."users" ("id") ON DELETE CASCADE ON UPDATE CASCADE, PRIMARY KEY ("id"));

CREATE INDEX "body_weight_histories_user_id_recorded_at" ON "gymbro"."body_weight_histories" ("user_id", "recorded_at");

CREATE TABLE IF NOT EXISTS "gymbro"."strength_records" ("id" UUID , "max_weight_kg" DECIMAL(7,2) NOT NULL, "repetitions" INTEGER NOT NULL, "estimated_one_rm" DECIMAL(7,2) NOT NULL, "achieved_at" TIMESTAMP WITH TIME ZONE, "deleted_at" TIMESTAMP WITH TIME ZONE, "user_id" UUID NOT NULL REFERENCES "gymbro"."users" ("id") ON DELETE CASCADE ON UPDATE CASCADE, "exercise_id" UUID NOT NULL REFERENCES "gymbro"."exercises" ("id") ON DELETE CASCADE ON UPDATE CASCADE, PRIMARY KEY ("id"));

CREATE INDEX "strength_records_user_id_exercise_id_estimated_one_rm" ON "gymbro"."strength_records" ("user_id", "exercise_id", "estimated_one_rm");

CREATE TABLE IF NOT EXISTS "gymbro"."session_mutations" ("id" UUID , "kind" VARCHAR(20) NOT NULL, "request_hash" VARCHAR(64) NOT NULL, "response" JSONB NOT NULL, "status_code" INTEGER NOT NULL, "created_at" TIMESTAMP WITH TIME ZONE NOT NULL, "session_id" UUID NOT NULL REFERENCES "gymbro"."training_sessions" ("id") ON DELETE CASCADE ON UPDATE CASCADE, PRIMARY KEY ("id"));

CREATE INDEX "session_mutations_session_id" ON "gymbro"."session_mutations" ("session_id");

CREATE TABLE gymbro.schema_migrations (version varchar(80) PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());

CREATE OR REPLACE FUNCTION gymbro_normalize_name(value text) RETURNS text
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $$
SELECT lower(regexp_replace(btrim(regexp_replace(normalize(value, NFD), U&'[\0300-\036f]', '', 'g')), '\s+', ' ', 'g')) $$;

CREATE OR REPLACE FUNCTION gymbro_exercise_name_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
NEW.normalized_name := gymbro_normalize_name(NEW.name);
PERFORM pg_advisory_xact_lock(hashtextextended(NEW.normalized_name,0));
IF EXISTS (SELECT 1 FROM exercises e WHERE e.id<>NEW.id AND e.normalized_name=NEW.normalized_name
AND (e.created_by_user_id IS NULL OR NEW.created_by_user_id IS NULL OR e.created_by_user_id=NEW.created_by_user_id))
THEN RAISE EXCEPTION 'El ejercicio ya existe en ese catálogo' USING ERRCODE='23505'; END IF;
RETURN NEW; END $$;

ALTER FUNCTION gymbro.gymbro_normalize_name(text) SET search_path TO gymbro, pg_temp;
ALTER FUNCTION gymbro.gymbro_exercise_name_guard() SET search_path TO gymbro, pg_temp;
CREATE UNIQUE INDEX exercises_official_name_unique ON gymbro.exercises(normalized_name) WHERE created_by_user_id IS NULL;
CREATE UNIQUE INDEX exercises_private_name_unique ON gymbro.exercises(created_by_user_id,normalized_name) WHERE created_by_user_id IS NOT NULL;
CREATE TRIGGER exercises_name_guard BEFORE INSERT OR UPDATE OF name,created_by_user_id,normalized_name ON gymbro.exercises FOR EACH ROW EXECUTE FUNCTION gymbro.gymbro_exercise_name_guard();

ALTER TABLE gymbro.user_rest_days ADD CONSTRAINT user_rest_days_weekday_range CHECK (weekday BETWEEN 0 AND 6);

ALTER TABLE gymbro.routine_schedules ADD CONSTRAINT routine_schedules_weekday_range CHECK (weekday BETWEEN 0 AND 6);

ALTER TABLE gymbro.routine_schedules ADD CONSTRAINT routine_schedules_valid_time_range CHECK (start_time < end_time);

ALTER TABLE gymbro.exercises ADD CONSTRAINT exercises_valid_type CHECK (training_type IN ('POWER','AEROBIC','ANAEROBIC'));

ALTER TABLE gymbro.exercises ADD CONSTRAINT exercises_valid_name CHECK (length(normalized_name) >= 2 AND normalized_name=gymbro_normalize_name(name));

ALTER TABLE gymbro.body_weight_histories ADD CONSTRAINT body_weight_histories_valid_weight CHECK (weight_kg > 0 AND weight_kg <= 500);

ALTER TABLE gymbro.routine_exercises ADD CONSTRAINT routine_exercises_valid_targets CHECK (target_sets > 0 AND min_reps > 0 AND max_reps >= min_reps AND rest_seconds >= 0);

ALTER TABLE gymbro.performed_sets ADD CONSTRAINT performed_sets_valid_values CHECK (set_number > 0 AND weight_kg >= 0 AND repetitions > 0 AND duration_seconds >= 0 AND actual_rest_seconds >= 0);

ALTER TABLE gymbro.session_mutations ADD CONSTRAINT session_mutations_valid_kind CHECK (kind IN ('START','EXERCISE','SET','REPLACE','FINISH')), ADD CONSTRAINT session_mutations_valid_status CHECK (status_code IN (200,201));
ALTER TABLE gymbro.welcome_plans ADD CONSTRAINT welcome_plan_source CHECK (source IN ('LOCAL','GEMINI','SKIPPED'));
