INSERT INTO "gymbro"."exercises" ("id","name","normalized_name","muscle_group","equipment","movement_pattern","description","video_url","training_type","created_by_user_id") VALUES ('3a53004c-bc68-508b-a8fb-e9f94c1dcbc3','Sentadilla','sentadilla','Piernas','Barra','Sentadilla','Apoyá la barra sobre la parte alta de la espalda. Flexioná caderas y rodillas con los talones apoyados y volvé a subir de forma controlada.','https://www.youtube.com/shorts/vCATDp5lDto','POWER',NULL),('d6cfaf96-ed98-5608-a34b-0fbefcfe40c9','Press banca','press banca','Pecho','Barra','Empuje horizontal','Acostate en el banco con los pies firmes y las escápulas apoyadas. Bajá la barra hacia el pecho y empujala sin rebotar.','https://www.youtube.com/shorts/H03Xuh4n3L8','POWER',NULL),('4d858a16-6a13-5dea-a36f-a452dc7d1503','Peso muerto rumano','peso muerto rumano','Isquiotibiales','Barra','Bisagra de cadera','Sostené la barra cerca de los muslos. Llevá la cadera hacia atrás con rodillas ligeramente flexionadas y regresá manteniendo la espalda estable.','https://www.youtube.com/shorts/JZA1_vAc7go','POWER',NULL),('4fe9c907-ddd7-5188-a2a0-86a92d5a2e26','Remo sentado','remo sentado','Espalda','Polea','Traccion horizontal','Sentate frente a la polea y tirá del agarre hacia el abdomen. Llevá los codos hacia atrás sin balancear el torso.','https://www.youtube.com/shorts/iyOM6y5ADAQ','POWER',NULL),('1ab46f81-e0c7-5de3-a13a-c21e7a6e2375','Press militar','press militar','Hombros','Mancuernas','Empuje vertical','Sostené las mancuernas a la altura de los hombros y empujalas por encima de la cabeza. Bajá controladamente sin arquear la zona lumbar.','https://www.youtube.com/shorts/vThYNRC1VNw','POWER',NULL),('021d927d-cb83-5186-af45-1ca15a8f7bc3','Dominadas','dominadas','Espalda','Barra fija','Traccion vertical','Colgate con las palmas hacia delante. Acercá el pecho a la barra flexionando los codos y descendé sin dejarte caer.','https://www.youtube.com/shorts/tzn_s-FGx1k','POWER',NULL),('d303f0dc-cf65-539b-a67d-4e53ba0f91f4','Hip thrust','hip thrust','Gluteos','Barra','Extension de cadera','Apoyá la parte alta de la espalda en un banco firme y la barra acolchada sobre la cadera. Elevá la pelvis sin hiperextender la espalda.','https://www.youtube.com/shorts/01geYxiQoFI','POWER',NULL),('a01f62ca-c0f9-5bf4-a979-85657b6c27ff','Curl de biceps','curl de biceps','Brazos','Mancuernas','Flexion de codo','Con una mancuerna en cada mano y las palmas hacia delante, flexioná los codos. Bajá lentamente sin balancear el cuerpo.','https://www.youtube.com/shorts/XcxJqfTdVKU','POWER',NULL),('361984d4-4c09-57da-a439-1f022fee89a6','Correr','correr','Cardio','Cinta o exterior','Carrera continua','Avanzá con pasos regulares, mirada al frente y brazos relajados. Mantené un ritmo que puedas sostener sin perder la postura.','https://www.youtube.com/shorts/7q2dIN2afWY','AEROBIC',NULL),('42ec50b4-0062-5e7c-ae69-6020b84d481b','Bicicleta','bicicleta','Cardio','Bicicleta','Pedaleo continuo','Ajustá el asiento para que la rodilla quede ligeramente flexionada al extender la pierna. Pedaleá de manera fluida sin balancear la cadera.','https://www.youtube.com/shorts/cjmCLXJ-Z4s','AEROBIC',NULL),('7eefdf55-425c-5b68-acd5-af6a4e03ed09','Caminata inclinada','caminata inclinada','Cardio','Cinta','Marcha','Caminá en una cinta con inclinación y velocidad controlables. Mantené pasos estables y evitá sostener tu peso en los pasamanos.','https://www.youtube.com/shorts/uTWg6-ug7es','AEROBIC',NULL),('ef8456af-07c5-5c3a-a717-c01bc3a79ede','Eliptica','eliptica','Cardio','Eliptica','Cardio continuo','Apoyá los pies completos sobre los pedales. Mové piernas y brazos de forma coordinada, con el torso erguido.','https://www.youtube.com/shorts/bwg4GNK7L5U','AEROBIC',NULL),('6ac80be3-dacd-5012-a307-a055e072ce41','Remo continuo','remo continuo','Cuerpo completo','Remo ergometro','Cardio continuo','En el ergómetro, empujá primero con las piernas, abrí suavemente la cadera y acercá el agarre al abdomen. Regresá en orden inverso.','https://www.youtube.com/shorts/iO2jTI2VU_o','AEROBIC',NULL),('1755a4ad-4e71-549b-a71f-19b28c970ace','Sprints','sprints','Piernas','Pista o cinta','Carrera por intervalos','Tras entrar en calor, acelerá progresivamente y corré rápido durante el tramo indicado. Desacelerá con espacio suficiente y recuperate antes de repetir.','https://www.youtube.com/shorts/hcHYlJNqY_0','ANAEROBIC',NULL),('b7a19f04-9502-57df-a466-19f05969816d','Bicicleta por intervalos','bicicleta por intervalos','Piernas','Bicicleta','Pedaleo por intervalos','Alterná tramos de pedaleo intenso con tramos suaves según el reloj. Ajustá la resistencia para mantener el control del movimiento.','https://www.youtube.com/shorts/jyjVSAWEwXQ','ANAEROBIC',NULL),('72efa392-0499-5cb3-a500-07f0bb5402cf','Burpees','burpees','Cuerpo completo','Peso corporal','Acondicionamiento','Desde parado, apoyá las manos, llevá los pies atrás hasta una plancha y regresá. Incorporate y realizá un salto corto con aterrizaje suave.','https://www.youtube.com/shorts/vLU2HqIsj5Q','ANAEROBIC',NULL),('43be0506-5a39-52a5-a0f4-b1981d20b5c7','Kettlebell swing','kettlebell swing','Cuerpo completo','Kettlebell','Bisagra explosiva','Sujetá la pesa con ambas manos. Impulsala mediante una extensión de cadera, dejando los brazos acompañar sin levantarla con los hombros.','https://www.youtube.com/shorts/jFpAYmINRjU','ANAEROBIC',NULL),('745fba67-6962-525d-a03b-3642045fafde','Saltar cuerda','saltar cuerda','Cardio','Cuerda','Saltos por intervalos','Girá la cuerda desde las muñecas y realizá saltos bajos con ambos pies. Aterrizá suavemente con rodillas ligeramente flexionadas.','https://www.youtube.com/shorts/xzBcNN_I0S4','ANAEROBIC',NULL),('deebfcbc-20b6-5216-ae03-4f519bbe4271','Trote suave','trote suave','Cardio','Exterior','Carrera continua','Trotá con pasos cortos y un ritmo cómodo. Dejá los hombros relajados y acompañá con los brazos.','https://www.youtube.com/shorts/4zcmx0iICDg','AEROBIC',NULL),('1aed9df4-688e-5cc2-a0df-662b684b51c5','Cam