ALTER TABLE "gymbro"."training_sessions" ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
ALTER TABLE "gymbro"."performed_exercises" ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
ALTER TABLE "gymbro"."performed_sets" ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
ALTER TABLE "gymbro"."body_weight_histories" ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
ALTER TABLE "gymbro"."strength_records" ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
CREATE INDEX IF NOT EXISTS users_deleted_at_idx ON "gymbro"."users" (deleted_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS exercises_deleted_at_idx ON "gymbro"."exercises" (deleted_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS routines_deleted_at_idx ON "gymbro"."routines" (deleted_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS routine_days_deleted_at_idx ON "gymbro"."routine_days" (deleted_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS routine_exercises_deleted_at_idx ON "gymbro"."routine_exercises" (deleted_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS training_sessions_deleted_at_idx ON "gymbro"."training_sessions" (deleted_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS performed_exercises_deleted_at_idx ON "gymbro"."performed_exercises" (deleted_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS performed_sets_deleted_at_idx ON "gymbro"."performed_sets" (deleted_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS body_weight_histories_deleted_at_idx ON "gymbro"."body_weight_histories" (deleted_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS strength_records_deleted_at_idx ON "gymbro"."strength_records" (deleted_at) WHERE deleted_at IS NOT NULL;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='gymbro_backend') THEN
REVOKE DELETE ON "gymbro"."users","gymbro"."exercises","gymbro"."routines","gymbro"."routine_days","gymbro"."routine_exercises","gymbro"."training_sessions","gymbro"."performed_exercises","gymbro"."performed_sets","gymbro"."body_weight_histories","gymbro"."strength_records" FROM gymbro_backend;
END IF; END $$;
INSERT INTO "gymbro".schema_migrations(version) VALUES ('20261022_soft_delete') ON CONFLICT(version) DO NOTHING;

ALTER TABLE "gymbro".users ADD COLUMN IF NOT EXISTS leaderboard_opt_in boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS "gymbro".legal_acceptances (
 id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES "gymbro".users(id) ON DELETE RESTRICT,
 version varchar(80) NOT NULL, document_hash varchar(64) NOT NULL, documents jsonb NOT NULL,
 terms_accepted boolean NOT NULL CHECK(terms_accepted),
 privacy_acknowledged boolean NOT NULL CHECK(privacy_acknowledged),
 adult_confirmed boolean NOT NULL CHECK(adult_confirmed),
 sports_data_consent boolean NOT NULL, accepted_at timestamptz NOT NULL
);
CREATE INDEX IF NOT EXISTS legal_acceptances_user_id_accepted_at ON "gymbro".legal_acceptances(user_id,accepted_at);
REVOKE ALL ON "gymbro".legal_acceptances FROM PUBLIC;
DO $$ DECLARE r text; BEGIN
FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN
EXECUTE format('REVOKE ALL ON "gymbro".legal_acceptances FROM %I',r);
END IF; END LOOP;
IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='gymbro_backend') THEN
GRANT SELECT, INSERT ON "gymbro".legal_acceptances TO gymbro_backend;
REVOKE UPDATE, DELETE ON "gymbro".legal_acceptances FROM gymbro_backend;
END IF; END $$;
INSERT INTO "gymbro".schema_migrations(version) VALUES ('20261022_legal') ON CONFLICT DO NOTHING;

ALTER TABLE "gymbro".users ADD COLUMN IF NOT EXISTS password_changed_at timestamptz;
INSERT INTO "gymbro".schema_migrations(version) VALUES ('20261025_password_recovery') ON CONFLICT DO NOTHING;

ALTER TABLE "gymbro".users ADD COLUMN IF NOT EXISTS ai_week_start timestamptz;
ALTER TABLE "gymbro".users ADD COLUMN IF NOT EXISTS ai_weekly_used integer NOT NULL DEFAULT 0;
DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='"gymbro".users'::regclass AND conname='users_ai_weekly_used_range') THEN
 ALTER TABLE "gymbro".users ADD CONSTRAINT users_ai_weekly_used_range CHECK (ai_weekly_used BETWEEN 0 AND 3);
 END IF;
END $$;
INSERT INTO "gymbro".schema_migrations(version) VALUES ('20261026_ai_weekly_quota') ON CONFLICT DO NOTHING;

ALTER TABLE "gymbro".exercises ADD COLUMN IF NOT EXISTS description text;
ALTER TABLE "gymbro".exercises ADD COLUMN IF NOT EXISTS video_url text;
COMMENT ON COLUMN "gymbro".exercises.video_url IS 'Enlace directo a un video de YouTube o TikTok. No almacena el archivo.';
UPDATE "gymbro".exercises AS exercise
SET description=COALESCE(NULLIF(btrim(exercise.description),''),guide.description),
    video_url=COALESCE(NULLIF(btrim(exercise.video_url),''),guide.video_url)
FROM (VALUES ('sentadilla','Apoyá la barra sobre la parte alta de la espalda. Flexioná caderas y rodillas con los talones apoyados y volvé a subir de forma controlada.','https://www.youtube.com/shorts/vCATDp5lDto'),
